    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Population: adults (≥ 18 years) with non-specific MSDs ... managed in primary care; Intervention: DA to physiotherapy. Comparator: GP-referred pathway (referral-based usual care); Primary outcome: GP workload (number/frequency of GP consultations); Secondary outcomes: ... Designs included: RCTs and observational comparative studies (cohort, case-control, quasi-experimental).",
      "reason": "Full PICO components, eligible designs, and setting (primary care) are explicitly specified in the Eligibility Criteria section."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "Qualitative-only reports, case series, protocols, and non-peer-reviewed documents were excluded.",
      "reason": "Publication status is addressed (non-peer-reviewed excluded), but no dissemination year or language restrictions are reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The synthesis is described as narrative (text_11), but no groups used in each synthesis are specified or linked to the review's comparisons; only a PICO mapping table (Additional file 3) is referenced without describing synthesis groupings."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "This combination was chosen to capture both efficacy data from experimental designs (RCTs) and realworld organizational impacts (observational studies) often unavailable in experimental settings.",
      "reason": "A rationale is provided for the notable restriction of including observational designs alongside RCTs and excluding systematic reviews from synthesis."
    }
  ],
  "confidence": 88
}

